/* ---------------------------- HERO ---------------------------- */
function Hero({ t }) {
  const [shown, setShown] = useState(0);
  useEffect(() => {
    setShown(0);
  }, [t]);
  useEffect(() => {
    if (shown >= t.hero.lines.length) return;
    const d = setTimeout(() => setShown((s) => s + 1), shown === 0 ? 600 : 1400);
    return () => clearTimeout(d);
  }, [shown, t]);

  return (
    <section className="hero">
      <div className="aurora-wash" />
      <div className="hero-inner">
        {t.hero.lines.map((line, i) => (
          <p
            key={i}
            className={`hero-line ${i < shown ? "is-in" : ""} ${
              i === 0 ? "hero-line--lead" : ""
            }`}
          >
            {line}
          </p>
        ))}
      </div>
      <div className="scroll-cue">
        <span>{t.hero.cue}</span>
        <div className="scroll-cue-line" />
      </div>
    </section>
  );
}

