/* ------------------- EDUCATION & EXPERIENCE ------------------- */
function EduExperience({ t }) {
  const [active, setActive] = useState(0);
  const [ref, visible] = useOnScreen(0.15);
  const dotRef = useRef(null);
  const itemRefs = useRef([]);

  useEffect(() => {
    setActive(0);
  }, [t]);

  useEffect(() => {
    const el = itemRefs.current[active];
    const dot = dotRef.current;
    if (el && dot) dot.style.top = `${el.offsetTop + el.offsetHeight / 2}px`;
  }, [active, t]);

  return (
    <section className="edu" ref={ref}>
      <span className="eyebrow">{t.edu.eyebrow}</span>
      <div className={`edu-body ${visible ? "is-in" : ""}`}>
        <div className="edu-rail">
          <div className="edu-rail-line" />
          <div className="edu-rail-dot" ref={dotRef} />
        </div>
        <div className="edu-list">
          {t.edu.items.map((item, i) => (
            <div
              key={item.name}
              ref={(el) => (itemRefs.current[i] = el)}
              className={`edu-item ${active === i ? "is-active" : ""}`}
              onClick={() => setActive(i)}
            >
              <span className="edu-name">{item.name}</span>
              {active === i && (
                <div className="edu-detail">
                  <span className="edu-role">{item.role}</span>
                  <span className="edu-period">{item.period}</span>
                  <p>{item.detail}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

