/* ---------------------------- PROJECTS ---------------------------- */
function ProjectModal({ project, onClose }) {
  if (!project) return null;
  const img = PROJECT_IMAGES[project.title];
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-sheet" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close" onClick={onClose} aria-label="close">
          <X size={18} />
        </button>
        <div className="modal-image">
          {img ? (
            <img src={img} alt={project.title} />
          ) : (
            <span>{project.title.slice(0, 2).toUpperCase()}</span>
          )}
        </div>
        <div className="modal-content">
          <span className={`modal-tag ${project.status === "ongoing" ? "modal-tag--ongoing" : ""}`}>
            {project.tag}
          </span>
          <h3>{project.title}</h3>
          <p>{project.desc}</p>
        </div>
      </div>
    </div>
  );
}

function Projects({ t }) {
  const [open, setOpen] = useState(null);
  return (
    <section className="projects">
      <span className="eyebrow">{t.projects.eyebrow}</span>
      <div className="projects-grid">
        {t.projects.items.map((p) => {
          const img = PROJECT_IMAGES[p.title];
          return (
            <button key={p.title} className="project-folder" onClick={() => setOpen(p)}>
              <div
                className="project-cover"
                style={img ? { backgroundImage: `url(${img})` } : undefined}
              >
                <span className={`status-pill ${p.status === "ongoing" ? "status-pill--ongoing" : ""}`}>
                  {p.status === "ongoing" ? t.projects.ongoingLabel : t.projects.selectedLabel}
                </span>
              </div>
              <span className="project-title">{p.title}</span>
              <span className="project-tag">{p.tag}</span>
            </button>
          );
        })}
      </div>
      <ProjectModal project={open} onClose={() => setOpen(null)} />
    </section>
  );
}

