/* ---------------------------- STYLES ---------------------------- */
const CSS = `
:root{
  --bg:#06060a; --panel:#0b0c13; --ink:#EFEAE1; --dim:#8b8e9c;
  --blue:#2a5c8f; --violet:#6a4b8f; --emerald:#1f6b52; --gold:#C9A84C;
}
*{box-sizing:border-box;}
.pf-root{
  background:var(--bg); color:var(--ink); font-family:'Inter',sans-serif;
  overflow-x:hidden; position:relative;
}
.starfield{ position:fixed; inset:0; pointer-events:none; z-index:1; }
.star{ position:absolute; border-radius:50%; background:#EFEAE1; opacity:0; animation:twinkle ease-in-out infinite; }
.star--gold{ background:var(--gold); }
@keyframes twinkle{ 0%,100%{opacity:0;} 50%{opacity:0.85;} }

.pf-nav{
  position:fixed; top:0; left:0; right:0; z-index:40; display:flex; justify-content:space-between; align-items:center;
  padding:20px 32px; backdrop-filter:blur(6px); background:linear-gradient(rgba(6,6,10,0.55), transparent);
}
.pf-nav-mark{ font-family:'Space Grotesk',sans-serif; font-weight:600; font-size:14px; letter-spacing:0.04em; }
.lang-toggle{ background:none; border:1px solid #23242f; border-radius:20px; padding:6px 12px; cursor:pointer; font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--dim); display:flex; gap:5px; align-items:center; }
.lang-toggle .is-active{ color:var(--gold); }
.lang-sep{ opacity:0.4; }

.eyebrow{
  font-family:'JetBrains Mono',monospace; font-size:12px; letter-spacing:0.12em;
  color:var(--gold); text-transform:uppercase; display:block; margin-bottom:20px;
}
.accent-word{ color:var(--gold); }

.hero{ position:relative; min-height:100vh; display:flex; align-items:center; justify-content:center; padding:24px; z-index:2;}
.aurora-wash{
  position:absolute; inset:0; pointer-events:none;
  background:
    radial-gradient(ellipse 60% 40% at 20% 15%, rgba(42,92,143,0.18), transparent 60%),
    radial-gradient(ellipse 50% 35% at 80% 25%, rgba(106,75,143,0.16), transparent 60%),
    radial-gradient(ellipse 55% 45% at 50% 90%, rgba(31,107,82,0.14), transparent 60%);
  filter:blur(10px);
}
.hero-inner{ position:relative; max-width:720px; text-align:center; }
.hero-line{
  font-family:'Space Grotesk',sans-serif; font-weight:500; font-size:22px; line-height:1.5;
  color:var(--dim); opacity:0; transform:translateY(14px);
  transition:opacity 0.9s ease, transform 0.9s ease; margin:14px 0;
}
.hero-line.is-in{ opacity:1; transform:translateY(0); }
.hero-line--lead{ font-size:34px; color:var(--ink); font-weight:600; }
.scroll-cue{
  position:absolute; bottom:36px; left:50%; transform:translateX(-50%);
  display:flex; flex-direction:column; align-items:center; gap:8px;
  font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--dim); letter-spacing:0.15em;
}
.scroll-cue-line{ width:1px; height:34px; background:linear-gradient(var(--gold), transparent); animation:pulseLine 2.2s ease-in-out infinite; }
@keyframes pulseLine{ 0%,100%{opacity:0.3;} 50%{opacity:1;} }

section{ position:relative; max-width:1100px; margin:0 auto; padding:120px 32px; z-index:2;}
h2{ font-family:'Space Grotesk',sans-serif; font-weight:600; font-size:32px; line-height:1.3; max-width:640px; }

.about-grid{ display:grid; grid-template-columns:1.2fr 0.8fr; gap:60px; align-items:start;}
.about-text p{ font-size:16px; line-height:1.7; color:#c7c3ba; max-width:520px; margin-top:14px;}

.badge-wrap{ display:flex; justify-content:center; padding-top:44px; }
.badge{
  width:180px; height:220px; border-radius:14px; background:var(--panel);
  border:1px solid #23242f; position:relative; transform:translateY(-260px);
  transform-origin:top center; overflow:visible; opacity:0;
}
.badge--drop{ animation: dropBounce 1.1s cubic-bezier(.34,1.56,.64,1) forwards, sway 4.5s ease-in-out 1.1s infinite; }
@keyframes dropBounce{
  0%{ transform:translateY(-260px) rotate(0deg); opacity:0; }
  8%{ opacity:1; }
  60%{ transform:translateY(10px) rotate(3deg); }
  80%{ transform:translateY(-6px) rotate(-2deg); }
  100%{ transform:translateY(0) rotate(0deg); opacity:1; }
}
@keyframes sway{ 0%,100%{ transform:translateY(0) rotate(-2deg);} 50%{ transform:translateY(0) rotate(2deg);} }
.badge-clip{ position:absolute; top:-18px; left:50%; transform:translateX(-50%); width:2px; height:18px; background:#3a3d4c; }
.badge-photo{
  width:100%; height:100%; border-radius:14px; overflow:hidden; background:#14151c;
}
.badge-photo img{ width:100%; height:100%; object-fit:cover; display:block; filter:saturate(0.95) contrast(1.03); }

.edu-body{ display:grid; grid-template-columns:24px 1fr; gap:24px; opacity:0; transform:translateY(20px); transition:opacity 0.8s ease, transform 0.8s ease;}
.edu-body.is-in{ opacity:1; transform:translateY(0); }
.edu-rail{ position:relative; }
.edu-rail-line{ position:absolute; left:50%; top:0; bottom:0; width:1px; background:linear-gradient(var(--blue), var(--violet), var(--emerald)); opacity:0.5;}
.edu-rail-dot{
  position:absolute; left:50%; width:10px; height:10px; margin-left:-5px; border-radius:50%;
  background:var(--gold); box-shadow:0 0 12px 3px rgba(201,168,76,0.5);
  transition:top 0.5s cubic-bezier(.4,0,.2,1);
}
.edu-item{ padding:16px 0; border-bottom:1px solid #17181f; cursor:pointer; }
.edu-name{ font-family:'Space Grotesk',sans-serif; font-size:17px; color:var(--dim); transition:color 0.3s; }
.edu-item.is-active .edu-name{ color:var(--ink); }
.edu-detail{ margin-top:10px; display:flex; flex-direction:column; gap:4px; animation:fadeIn 0.4s ease; }
.edu-role{ font-size:14px; color:var(--gold); }
.edu-period{ font-family:'JetBrains Mono',monospace; font-size:11px; color:#666a78; }
.edu-detail p{ font-size:14px; line-height:1.6; color:#a9a59d; max-width:560px; margin-top:6px; }
@keyframes fadeIn{ from{opacity:0;} to{opacity:1;} }

.skills-title{ margin-bottom:40px; }
.skill-row{ display:flex; align-items:center; gap:28px; padding:18px 0; border-bottom:1px solid #14151c; flex-wrap:wrap;}
.skill-cat-name{ font-family:'JetBrains Mono',monospace; font-size:12px; color:var(--dim); width:190px; flex-shrink:0; text-transform:uppercase; letter-spacing:0.06em;}
.skill-tools{ display:flex; flex-wrap:wrap; gap:10px; }
.skill-tool{
  display:flex; align-items:center; gap:8px; padding:10px 16px; border-radius:8px; background:var(--panel); border:1px solid #22232e;
  font-size:13px; color:#c7c3ba; opacity:0; transform:translateX(40px);
  transition:opacity 0.55s cubic-bezier(.2,.8,.3,1.3), transform 0.55s cubic-bezier(.2,.8,.3,1.3);
}
.skill-tool.is-in{ opacity:1; transform:translateX(0); }
.skill-dot{ width:8px; height:8px; border-radius:50%; flex-shrink:0; box-shadow:0 0 6px currentColor; }

.projects-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:24px; margin-top:20px; }
.project-folder{
  text-align:left; background:var(--panel); border:1px solid #1c1d27; border-radius:12px; padding:0;
  cursor:pointer; overflow:hidden; color:inherit; font:inherit; transition:transform 0.3s ease, border-color 0.3s ease;
}
.project-folder:hover{ transform:translateY(-4px); border-color:#3a3d52; }
.project-cover{
  height:130px; display:flex; align-items:flex-start; justify-content:flex-end; padding:12px;
  background-size:cover; background-position:center;
  background-color:#12131b;
  background-image:linear-gradient(135deg, rgba(42,92,143,0.22), rgba(106,75,143,0.16));
  position:relative;
}
.project-cover::after{
  content:""; position:absolute; inset:0;
  background:linear-gradient(180deg, rgba(6,6,10,0) 40%, rgba(6,6,10,0.55) 100%);
}
.status-pill{ position:relative; z-index:1; font-family:'JetBrains Mono',monospace; font-size:10px; padding:4px 10px; border-radius:20px; background:rgba(31,107,82,0.35); color:#7fd9b8; border:1px solid rgba(31,107,82,0.5); backdrop-filter:blur(3px);}
.status-pill--ongoing{ background:rgba(201,168,76,0.28); color:var(--gold); border-color:rgba(201,168,76,0.5);}
.project-title{ display:block; font-family:'Space Grotesk',sans-serif; font-size:16px; padding:16px 18px 2px; }
.project-tag{ display:block; font-family:'JetBrains Mono',monospace; font-size:10.5px; color:var(--dim); padding:0 18px 18px; }

.modal-backdrop{ position:fixed; inset:0; background:rgba(3,3,6,0.75); backdrop-filter:blur(4px); display:flex; align-items:center; justify-content:center; z-index:50; animation:fadeIn 0.25s ease; padding:24px;}
.modal-sheet{
  background:var(--panel); border:1px solid #23242f; border-radius:16px; max-width:560px; width:100%;
  display:flex; gap:20px; padding:26px; position:relative; animation:sheetUp 0.35s cubic-bezier(.2,.8,.3,1.1);
}
@keyframes sheetUp{ from{ opacity:0; transform:translateY(30px);} to{opacity:1; transform:translateY(0);} }
.modal-close{ position:absolute; top:14px; right:14px; background:none; border:none; color:var(--dim); cursor:pointer; }
.modal-image{ width:110px; height:110px; flex-shrink:0; border-radius:10px; overflow:hidden; background:linear-gradient(135deg, rgba(31,107,82,0.3), rgba(42,92,143,0.2)); display:flex; align-items:center; justify-content:center; color:var(--gold); font-family:'Space Grotesk',sans-serif; font-size:22px; font-weight:600;}
.modal-image img{ width:100%; height:100%; object-fit:cover; display:block; }
.modal-tag{ font-family:'JetBrains Mono',monospace; font-size:11px; color:#7fd9b8; }
.modal-tag--ongoing{ color:var(--gold); }
.modal-content h3{ font-family:'Space Grotesk',sans-serif; font-size:22px; margin:8px 0 10px; }
.modal-content p{ font-size:14px; line-height:1.6; color:#a9a59d; }

.final-grid{ display:grid; grid-template-columns:0.8fr 1.2fr; gap:60px; align-items:start; margin-top:20px;}
.final-badge-col{ display:flex; justify-content:center; padding-top:20px; position:sticky; top:110px; }
.final-block{ margin-bottom:30px; }
.final-block h3{ font-family:'Space Grotesk',sans-serif; font-size:15px; color:var(--gold); text-transform:uppercase; letter-spacing:0.08em; margin-bottom:12px;}
.final-block p{ font-size:15px; line-height:1.7; color:#c7c3ba; max-width:460px; }
.hobby-tags{ display:flex; flex-wrap:wrap; gap:8px; }
.hobby-tag{ padding:8px 14px; border-radius:20px; border:1px solid #2a2c39; font-size:13px; color:#c7c3ba; }
.hobby-tag--soft{ border-color:rgba(201,168,76,0.25); color:#d8cba0; }
.connect-links{ display:flex; gap:12px; flex-wrap:wrap; align-items:center; }
.connect-link{ display:flex; align-items:center; gap:8px; color:var(--ink); text-decoration:none; font-size:13px; padding:10px 14px; border:1px solid #23242f; border-radius:10px; transition:border-color 0.3s, color 0.3s; }
.connect-link:hover{ border-color:var(--gold); color:var(--gold); }
.connect-link--icon-only{ padding:10px; border-radius:50%; }

.pf-footer{ display:flex; justify-content:space-between; padding:32px; font-family:'JetBrains Mono',monospace; font-size:11px; color:#4c5062; border-top:1px solid #14151c; position:relative; z-index:2;}

@media (max-width:760px){
  .about-grid, .projects-grid{ grid-template-columns:1fr; }
  .final-grid{ grid-template-columns:1fr; }
  .final-badge-col{ position:static; }
  .edu-body{ grid-template-columns:16px 1fr; }
  h2, .hero-line--lead{ font-size:24px; }
  .skill-cat-name{ width:100%; margin-bottom:4px; }
}
@media (prefers-reduced-motion: reduce){
  *{ animation-duration:0.01ms !important; transition-duration:0.01ms !important; }
}
`;
